//! Explicit full baseline update on the SAME resident project session.
use super::{protocol,transport,selected_report_wire as wire};use crate::{request::Command,runner_host::{BuildHost,BaselineUpdateRequest}};use std::{error::Error,io,path::PathBuf};
fn invalid(text:&str)->io::Error{io::Error::new(io::ErrorKind::InvalidInput,text)}
pub(super)fn qualify(r:&BaselineUpdateRequest)->io::Result<()>{r.qualify()?;let bytes=r.selectors.capacity().checked_mul(std::mem::size_of::<String>()).and_then(|n|r.selectors.iter().try_fold(n,|n,selector|n.checked_add(selector.capacity()))).ok_or_else(||io::Error::from(io::ErrorKind::OutOfMemory))?;if bytes>protocol::MAX_FRAME{return Err(io::Error::new(io::ErrorKind::OutOfMemory,"baseline selectors exceed actual protocol metadata envelope"))}super::build_admission::validate(&r.build).map_err(io::Error::other)?;super::generation::validate_cache(&r.build)}
fn invocation(args:&[String])->Result<BaselineUpdateRequest,Box<dyn Error>>{let(mut root,mut mode,mut no_gen,mut at)=(None,None,false,0);let mut selectors=Vec::new();while let Some(arg)=args.get(at){at+=1;match arg.as_str(){"--workspace"=>{let value=args.get(at).ok_or_else(||invalid("baseline workspace value missing"))?;at+=1;if root.replace(PathBuf::from(value)).is_some(){return Err(invalid("duplicate baseline workspace").into())}},"--mode"=>{let value=args.get(at).ok_or_else(||invalid("baseline mode missing"))?;at+=1;let selected=match value.as_str(){"update"=>dq_analyze::native_baseline_update_wire::Mode::Update,"seed"=>dq_analyze::native_baseline_update_wire::Mode::Seed,"migrate"=>dq_analyze::native_baseline_update_wire::Mode::Migrate,_=>return Err(invalid("unknown baseline mode").into())};if mode.replace(selected).is_some(){return Err(invalid("duplicate baseline mode").into())}},"--no-gen" if !no_gen=>no_gen=true,"--lint"=>{let before=selectors.len();while let Some(value)=args.get(at){if value.starts_with("--"){break}selectors.push(value.clone());at+=1;}if selectors.len()==before{return Err(invalid("baseline --lint values missing").into())}},_=>return Err(invalid("native baseline update accepts only workspace and caller no-gen intent").into())}}
 let root=root.filter(|p|p.is_absolute()).ok_or_else(||invalid("baseline update needs absolute workspace"))?;let root=std::fs::canonicalize(root)?;let cache=std::fs::canonicalize(crate::request::client_cache_root()?)?;
 let Command::Build(build)=crate::cli::parse(&["prepare-query".into(),root.join("deepquarry.dme").to_string_lossy().into_owned()])?else{return Err(invalid("baseline update needs actual PrepareQuery").into())};let mut build=*build;build.no_cache=true;build.exact_inputs=true;build.progress_enabled=false;build.workers=2;build.timeout_seconds=Some(300);build.engine_template=None;build.bootstrap_catalog=false;build.cache_root=Some(cache);
 use crate::policy_request::{AnalysisContext,PolicyInputRequest,WorkspacePolicyRequest,WorkspaceAuxiliaryQuestion as Q};let roots=Q::authored_doc_ui_roots(Q::PRIVATE_FULL_REGISTRY).ok_or_else(||invalid("full registry authored roots absent"))?;build.policy_inputs=Some(PolicyInputRequest{analysis_context:Some(AnalysisContext::OriginalAnalyze0290),workspace:Some(WorkspacePolicyRequest{root:root.clone(),recursive_roots:roots.iter().map(|p|root.join(p)).collect(),configuration:root.join("tools/ci/lint_scopes.toml")}),..Default::default()});let request=BaselineUpdateRequest{build,mode:mode.unwrap_or_default(),no_gen,selectors};qualify(&request)?;Ok(request)}
pub fn run_cli(args:&[String])->Result<(),Box<dyn Error>>{let request=invocation(args)?;let(root,cache)=BuildHost::native_registry_check_paths(&request.build)?;let mode=request.mode;let no_gen=request.no_gen;let selection=dq_analyze::full_registry_check_selection_wire::SelectionBinding::for_selectors_using(&request.selectors,&||super::control::checkpoint())?;let mut stream=super::connect_generation()?;transport::set_timeout(&mut stream,transport::BUILD_DEADLINE)?;protocol::send(&mut stream,&protocol::Request::BaselineUpdate(request))?;wire::receive_baseline_update(&mut stream,&cache,&root,mode,no_gen,selection)?.publish(&mut io::stdout().lock()).map_err(Into::into)}
